namespace TutorFlow.Core.Asistente;

public sealed class ConfiguracionAsistente
{
    private const int BytesDelMarcadorAleatorio = 32;
    private const int TokensDeEntradaReservados = 8000;
    private const int TokensDeSalidaReservados = 2000;
    private const int MinimoPermitido = 1;

    public const int RelevanciaMinimaPorDefecto = 2;
    public const int ApoyoMinimoPorDefecto = 2;
    public const decimal ReservaSinPrecioPorDefectoUsd = 0.01m;

    public ConfiguracionAsistente(
        PrecioModelo? precio,
        string? marcadorCanarioConfigurado,
        IReadOnlyCollection<string>? codigosAsignatura,
        decimal? reservaPorPeticionUsd = null,
        int relevanciaMinima = RelevanciaMinimaPorDefecto,
        int apoyoMinimoRespaldo = ApoyoMinimoPorDefecto,
        IReadOnlyList<AsignaturaCatalogo>? catalogo = null,
        decimal reservaSinPrecioUsd = ReservaSinPrecioPorDefectoUsd,
        Action<string>? advertir = null,
        AjustesDelModelo? ajustes = null)
    {
        Catalogo = catalogo ?? throw new ArgumentNullException(nameof(catalogo));
        Advertir = AdvertenciaOSilencio(advertir);
        Precio = precio;
        MarcadorCanario = string.IsNullOrWhiteSpace(marcadorCanarioConfigurado)
            ? Convert.ToHexString(RandomNumberGenerator.GetBytes(BytesDelMarcadorAleatorio))
            : marcadorCanarioConfigurado;
        CodigosAsignatura = CodigosOCatalogo(codigosAsignatura, Catalogo);
        Ajustes = ajustes ?? new AjustesDelModelo();
        ReservaPorPeticionUsd = reservaPorPeticionUsd is > 0m ? reservaPorPeticionUsd.Value : ReservaPorDefecto(precio, reservaSinPrecioUsd);
        RelevanciaMinima = Math.Max(MinimoPermitido, relevanciaMinima);
        ApoyoMinimoRespaldo = Math.Max(MinimoPermitido, apoyoMinimoRespaldo);
    }

    private readonly HashSet<string> _advertidas = [];

    public Action<string> Advertir { get; }

    public void AdvertirUnaVez(string mensaje)
    {
        lock (_advertidas)
        {
            if (_advertidas.Add(mensaje))
            {
                Advertir(mensaje);
            }
        }
    }

    public AjustesDelModelo Ajustes { get; }

    public PrecioModelo? Precio { get; }

    public string MarcadorCanario { get; }

    public IReadOnlyCollection<string> CodigosAsignatura { get; }

    public IReadOnlyList<AsignaturaCatalogo> Catalogo { get; }

    public decimal ReservaPorPeticionUsd { get; }

    public int RelevanciaMinima { get; }

    public int ApoyoMinimoRespaldo { get; }

    private static Action<string> AdvertenciaOSilencio(Action<string>? advertir) => advertir ?? (_ => { });

    private static IReadOnlyCollection<string> CodigosOCatalogo(IReadOnlyCollection<string>? codigos, IReadOnlyList<AsignaturaCatalogo> catalogo) =>
        codigos ?? [.. catalogo.Select(asignatura => asignatura.Codigo)];
using Microsoft.AspNetCore.Hosting;
using TutorFlow.Infrastructure.Configuracion;

namespace TutorFlow.Api;

internal sealed partial class ValidacionDeArranque : IStartupFilter
{
    private static readonly string[] VariablesDePrecio = ["LLM_PRECIO_ENTRADA", "LLM_PRECIO_SALIDA"];
    private static readonly string[] ClavesDeLimitesOpcionales = ["Limites:PreguntasPorMinutoPorIp", "Limites:PresupuestoDiarioUsd"];

    private readonly IConfiguration _configuracion;
    private readonly IVariablesEntorno _variables;
    private readonly ILogger _logger;

    public ValidacionDeArranque(IConfiguration configuracion, IVariablesEntorno variables, ILoggerFactory fabricaDeLogs)
    {
        _configuracion = configuracion;
        _variables = variables;
        _logger = fabricaDeLogs.CreateLogger("TutorFlow.Configuracion");
    }

    public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> siguiente)
    {
        var efectiva = ConEntorno();
        var errores = ValidadorDeConfiguracion.Validar(efectiva);
        if (errores.Count > 0)
        {
            throw new InvalidOperationException(string.Join("\n", errores));
        }

        foreach (var advertencia in ValidadorDeConfiguracion.Advertencias(efectiva))
        {
            RegistrarAdvertencia(_logger, advertencia);
        }

        RegistrarLimitesSinTope(efectiva);
        RegistrarProxies(efectiva);
        return siguiente;
    }

    private void RegistrarLimitesSinTope(IConfiguration efectiva)
    {
        foreach (var clave in ClavesDeLimitesOpcionales.Where(clave => string.IsNullOrWhiteSpace(efectiva[clave])))
        {
            RegistrarLimiteSinTope(_logger, clave);
        }
    }

    private void RegistrarProxies(IConfiguration efectiva)
    {
        var ips = ProxyConfiable.Efectivas(efectiva);
        if (ips.Count > 0)
        {
            var texto = string.Join(", ", ips);
            RegistrarProxyConfiable(_logger, texto);
        }
    }

    private IConfiguration ConEntorno()
    {
        var delEntorno = VariablesDePrecio
            .Select(nombre => new KeyValuePair<string, string?>(nombre, _variables.Leer(nombre)))
            .Where(par => par.Value is not null);
        return new ConfigurationBuilder().AddConfiguration(_configuracion).AddInMemoryCollection(delEntorno).Build();
    }

    [LoggerMessage(Level = LogLevel.Information, Message = "Límite sin tope: {Clave}")]
    private static partial void RegistrarLimiteSinTope(ILogger logger, string clave);

    [LoggerMessage(Level = LogLevel.Information, Message = "IPs de proxy de confianza: {Ips}.")]
    private static partial void RegistrarProxyConfiable(ILogger logger, string ips);

    [LoggerMessage(Level = LogLevel.Warning, Message = "{Mensaje}")]
    internal static partial void RegistrarAdvertencia(ILogger logger, string mensaje);
}

