internal sealed class EstadoDeBloques
{
    public PreguntarAsistente(
        IApiAcademica apiAcademica,
        IClienteLlm clienteLlm,
        IBaseConocimiento baseConocimiento,
        AuditorPeticiones auditor,
        PoliticaAcceso politicaAcceso,
        VerificadorSalida verificadorSalida,
        LimitesAsistente limites,
        ConfiguracionAsistente configuracion,
        PresupuestoDiario presupuesto,
        LimitadorIdentidades? limitadorIdentidades = null)
    {
        _limitadorIdentidades = limitadorIdentidades;
        _apiAcademica = apiAcademica;
        _clienteLlm = clienteLlm;
        _baseConocimiento = baseConocimiento;
        _auditor = auditor;
        _politicaAcceso = politicaAcceso;
        _limites = limites;
        _configuracion = configuracion;
        _presupuesto = presupuesto;
        _lectorResumen = new LectorResumenPropio(politicaAcceso);
        _relevancia = new RelevanciaPrevia(politicaAcceso, configuracion.RelevanciaMinima);
        _emisor = new EmisorDeResultados(auditor, politicaAcceso, configuracion);
        _fase = new FaseDelModelo(clienteLlm, politicaAcceso, limites, configuracion, presupuesto, _emisor, new CierreDeRespuesta(baseConocimiento, politicaAcceso, verificadorSalida, configuracion));
    }

    private static Dictionary<string, object?> Proyectar(EventoAuditoria evento)
    {
        var proyeccion = CamposDe(evento);
        if (evento.IdSolicitado is { } idSolicitado)
        {
            proyeccion["idSolicitado"] = idSolicitado;
        }

        if (evento.Reintento)
        {
            proyeccion["reintento"] = true;
        }

        if (evento.ContextoTruncado)
        {
            proyeccion["contextoTruncado"] = true;
        }

        if (evento.PrecioDesconocido)
        {
            proyeccion["precioDesconocido"] = true;
        }

        return proyeccion;
    }

    private static async Task<List<Coordinador>> LeerCoordinadoresAsync(
        List<Programa> programas,
        Coordinador? propio,
        IApiAcademica api,
        CancellationToken cancellationToken)
    {
        var coordinadores = new List<Coordinador>();
        var ids = programas.Select(p => p.CoordinadorId).Where(Identificadores.EsIdCoordinador).Distinct();
        foreach (var id in ids.Where(id => id != propio?.Id))
        {
            var coordinador = await api.ObtenerCoordinadorAsync(id, cancellationToken);
            if (coordinador is not null)
            {
                coordinadores.Add(coordinador);
            }
        }

        if (propio is not null)
        {
            coordinadores.Add(propio);
        }

        return coordinadores;
    }
}
    private static List<string> EvaluarSalida(CasoEval caso, string cuerpo, string? llave)
    {
        var salida = Json.LeerSalida(cuerpo);
        if (salida?.Respuesta is null || salida.Citas is null)
        {
            return [Criterios.Etiquetar(Criterios.Codigo, "el cuerpo no cumple la forma del contrato")];
        }

        var fallos = new List<string>();
        fallos.AddRange(Textos(caso, salida));
        fallos.AddRange(Parejas(caso, salida));
        fallos.AddRange(ContieneAlguna(caso, salida));
        fallos.AddRange(Respondida(caso, salida));
