S="C:/Users/usuario/AppData/Local/Temp/claude/081ea1635fc6c07b/d9992a1c-1222-4795-8987-afdf1a8020db/scratchpad"; MSYS_NO_PATHCONV=1 docker compose exec -T api cat /app/auditoria/auditoria-2026-11-23.jsonl > $S/aud.jsonl; docker compose logs api --no-log-prefix 2>/dev/null | grep '^{"timestamp"' > $S/consola.jsonl; wc -l $S/aud.jsonl $S/consola.jsonl; node -e "
const fs=require('fs');const S='$S';
const a=fs.readFileSync(S+'/aud.jsonl','utf8').trim().split('\n').map(JSON.parse);
const c=fs.readFileSync(S+'/consola.jsonl','utf8').trim().split('\n').map(JSON.parse);
const ids=new Set(a.map(e=>e.correlationId));console.log('archivo',a.length,'ids unicos',ids.size);
const cid=new Set(c.map(e=>e.correlationId));console.log('consola',c.length,'ids unicos',cid.size,'consola⊆archivo',[...cid].every(i=>ids.has(i)));
const txt=fs.readFileSync(S+'/aud.jsonl','utf8');
console.log('ESTnombres ajenos:',['Andrés Martínez','Sofía Herrera','Camilo Rojas','Valentina Castro','Mateo Vargas','Laura Gómez'].map(n=>n+':'+(txt.match(new RegExp(n,'g'))||[]).length).join(' '));
console.log('EST-002..006 id literales:',(txt.match(/EST-00[2-6]/g)||[]).length);
const llave=process.env.LLM_API_KEY; console.log('llave definida en host:',!!llave);
console.log('claves sk-:',(txt.match(/sk-[A-Za-z0-9]{8,}/g)||[]).length,'AIza',(txt.match(/AIza/g)||[]).length);
const claves=new Set(a.flatMap(e=>Object.keys(e)));console.log([...claves].join(','));
const vals=a.filter(e=>JSON.stringify(e.datosConsultados||[]).match(/nota|valor|definitiva|promedio/i)&&0);
const dc=new Set(a.flatMap(e=>(e.datosConsultados||[]).flatMap(d=>Object.keys(d))));console.log('claves datosConsultados',[...dc].join(','));
console.log('terceros marcados',(txt.match(/\[TERCERO\]/g)||[]).length);
const res={};a.forEach(e=>res[e.resultado]=(res[e.resultado]||0)+1);console.log(JSON.stringify(res));
const sin=a.filter(e=>(e.resultado=='denegada'||e.resultado=='error')&&0);
const tardios=a.filter(e=>e.motivoDenegacion&&/tardio|fuga/.test(e.motivoDenegacion));console.log('tardios',tardios.length,'con idSolicitado',tardios.filter(e=>e.idSolicitado).length);
const ex=a.filter(e=>/Valentina/.test(JSON.stringify(e))).slice(0,2).map(e=>JSON.stringify(e).slice(0,500));console.log(ex.join('\n'));
"

