const sec=a.filter(e=>/Valentina|Andrés|Sofía/.test(JSON.stringify({...e,pregunta:''})));console.log('nombres fuera de pregunta',sec.length);
const sinEvt=a.filter(e=>e.resultado===undefined).map(e=>e.evento);console.log([...new Set(sinEvt)]);
