const idsEnPregunta=a.filter(e=>/EST-00[2-6]/.test(e.pregunta||'')&&e.resultado=='denegada').length;console.log('ids ajenos crudos en pregunta de denegadas',idsEnPregunta);
const bad=a.filter(e=>e.resultado=='denegada'&&e.usuario.rol=='estudiante'&&/\b[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+ [A-ZÁÉÍÓÚÑ][a-záéíóúñ]+/.test(e.pregunta)&&/Martínez|Herrera|Castro|Rojas|Vargas/.test(e.pregunta));console.log('denegadas con apellido ajeno sin enmascarar',bad.length);bad.slice(0,3).forEach(e=>console.log(e.pregunta));
"

